for name,change in DATA.items():
    p=Path(name);text=p.read_text();digest=sha256(text.encode()).hexdigest()
    if digest==change['after']:continue
    if digest!=change['before']:raise RuntimeError('Unexpected revision: '+name)
    for a,b,v in reversed(change['edits']):text=text[:a]+v+text[b:]
    if sha256(text.encode()).hexdigest()!=change['after']:raise RuntimeError('Checksum failed: '+name)
    p.write_text(text)
print('Progression polish applied.')
